using System;
using System.Collections.Generic;
using Framework.Grid;
using Framework.Pathfinding;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.Map;
using UnityEngine;

namespace Game.AI.Spatial
{
    /// <summary>
    /// 敵AIの探索地点や巡回地点に対する
    /// 空間評価と移動先の選定を行う。
    /// </summary>
    /// <remarks>
    /// 移動距離、訪問記憶、縄張り、行動傾向を使用する。
    /// 実際の経路探索や移動制御は行わない。
    /// Unityのメインスレッドで使用することを想定する。
    /// </remarks>
    public sealed class MazeEnemySpatialEvaluator : IDisposable
    {
        /// <summary>
        /// 距離評価に使用する基準距離。
        /// 単位はセル数。
        /// </summary>
        public const float ReferenceDistance = 5f;

        /// <summary>
        /// 評価値の同点判定に使用する許容誤差。
        /// </summary>
        private const float ScoreTolerance = 0.000001f;

        /// <summary>
        /// 評価対象の敵AIコンテキスト。
        /// </summary>
        private readonly MazeEnemyContext context;

        /// <summary>
        /// 縄張り評価システム。
        /// </summary>
        private readonly MazeEnemyTerritory territory;

        /// <summary>
        /// 評価対象のステージグリッド。
        /// </summary>
        private readonly GridMap<MazeCell> map;

        /// <summary>
        /// 自身から各セルへの最短移動距離マップ。
        /// </summary>
        private readonly GridDistanceMap<MazeCell> distanceMap;

        /// <summary>
        /// 最後に距離計算を試みた起点。
        /// </summary>
        private Vector2Int cachedOrigin;

        /// <summary>
        /// 距離マップの再計算が必要であるか。
        /// </summary>
        private bool isDirty = true;

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        private bool isDisposed;

        /// <summary>
        /// 距離マップの再計算回数。
        /// </summary>
        private long recalculationCount;

        /// <summary>
        /// 最後の候補選定で評価したセル数。
        /// </summary>
        private int lastCandidateCount;

        /// <summary>
        /// 評価対象の敵AIコンテキスト。
        /// </summary>
        public MazeEnemyContext Context => context;

        /// <summary>
        /// 使用する縄張り評価システム。
        /// </summary>
        public MazeEnemyTerritory Territory => territory;

        /// <summary>
        /// 現在の距離計算起点。
        /// </summary>
        /// <remarks>
        /// 移動途中の場合は次の到達予定セルを使用する。
        /// 無効な状態では既定値を返す。
        /// </remarks>
        public Vector2Int Origin =>
            IsValid
                ? context.IsTraversing
                    ? context.TargetCell
                    : context.CurrentCell
                : default;

        /// <summary>
        /// 空間評価を利用可能な状態であるか。
        /// </summary>
        public bool IsValid =>
            !isDisposed &&
            context.IsValid &&
            territory.IsValid;

        /// <summary>
        /// 距離マップの再計算が必要であるか。
        /// </summary>
        public bool IsDirty =>
            IsValid &&
            (isDirty || cachedOrigin != Origin);

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        public bool IsDisposed => isDisposed;

        /// <summary>
        /// 距離マップの再計算回数。
        /// </summary>
        public long RecalculationCount =>
            recalculationCount;

        /// <summary>
        /// 最後の候補選定で評価したセル数。
        /// </summary>
        public int LastCandidateCount =>
            lastCandidateCount;

        /// <summary>
        /// 空間評価システムを生成する。
        /// </summary>
        /// <param name="context">敵AIコンテキスト</param>
        /// <param name="territory">縄張り評価システム</param>
        /// <exception cref="ArgumentNullException">
        /// 必須の引数が指定されていない場合。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// 引数が無効、または異なる敵の情報である場合。
        /// </exception>
        public MazeEnemySpatialEvaluator(
            MazeEnemyContext context,
            MazeEnemyTerritory territory)
        {
            if (context == null)
            {
                throw new ArgumentNullException(
                    nameof(context));
            }

            if (territory == null)
            {
                throw new ArgumentNullException(
                    nameof(territory));
            }

            if (!context.IsValid)
            {
                throw new ArgumentException(
                    "無効な敵AIコンテキストです。",
                    nameof(context));
            }

            if (!territory.IsValid ||
                !ReferenceEquals(
                    territory.Context,
                    context))
            {
                throw new ArgumentException(
                    "縄張り評価システムが無効、" +
                    "またはコンテキストが一致していません。",
                    nameof(territory));
            }

            this.context = context;
            this.territory = territory;

            map = context.Map;

            distanceMap = new GridDistanceMap<MazeCell>(
                map,
                context.IsWalkable);

            map.CellChanged += HandleCellChanged;
        }

        /// <summary>
        /// 必要に応じて距離マップを更新する。
        /// </summary>
        /// <returns>
        /// 有効な距離マップを利用できる場合はtrue
        /// </returns>
        public bool Refresh()
        {
            if (!IsValid)
            {
                return false;
            }

            if (!IsDirty)
            {
                return distanceMap.IsCalculated;
            }

            Vector2Int origin = Origin;

            if (recalculationCount < long.MaxValue)
            {
                recalculationCount++;
            }

            // 計算例外が発生した場合は無効状態を維持する。
            isDirty = true;

            bool calculated =
                distanceMap.Calculate(origin);

            cachedOrigin = origin;

            isDirty = false;

            return calculated;
        }

        /// <summary>
        /// 距離マップを無効化する。
        /// 次回の評価要求時に再計算する。
        /// </summary>
        public void Invalidate()
        {
            if (IsValid)
            {
                isDirty = true;
            }
        }

        /// <summary>
        /// 起点から指定セルへの最短移動距離を取得する。
        /// </summary>
        /// <param name="position">対象のセル座標</param>
        /// <returns>
        /// 最短移動距離。
        /// 到達不可能または無効な場合は-1
        /// </returns>
        public int GetDistance(Vector2Int position)
        {
            if (!IsValid ||
                !map.IsInside(position) ||
                !Refresh())
            {
                return -1;
            }

            return distanceMap.GetDistance(position);
        }

        /// <summary>
        /// 指定されたセルに対する空間評価を行う。
        /// </summary>
        /// <param name="position">評価対象のセル座標</param>
        /// <param name="mode">空間評価方式</param>
        /// <param name="evaluation">空間評価結果</param>
        /// <returns>
        /// 有効な評価結果を取得できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 起点自身は移動先候補として評価しない。
        /// </remarks>
        public bool TryEvaluate(
            Vector2Int position,
            MazeEnemySpatialMode mode,
            out MazeEnemySpatialEvaluation evaluation)
        {
            evaluation = default;

            if (!IsSupportedMode(mode) ||
                !IsValid ||
                !map.IsInside(position) ||
                !Refresh())
            {
                return false;
            }

            int distance =
                distanceMap.GetDistance(position);

            return TryEvaluateInternal(
                position,
                distance,
                mode,
                out evaluation);
        }

        /// <summary>
        /// 指定された距離範囲から最適な移動先を選定する。
        /// </summary>
        /// <param name="mode">空間評価方式</param>
        /// <param name="evaluation">最適な候補の評価結果</param>
        /// <param name="minDistance">最小移動距離</param>
        /// <param name="maxDistance">最大移動距離</param>
        /// <returns>
        /// 有効な移動先を選定できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 同点の場合は移動距離が短い候補を優先する。
        /// 距離も同じ場合はグリッドの列挙順を使用する。
        /// </remarks>
        public bool TrySelectBestPosition(
            MazeEnemySpatialMode mode,
            out MazeEnemySpatialEvaluation evaluation,
            int minDistance = 1,
            int maxDistance = int.MaxValue)
        {
            evaluation = default;

            lastCandidateCount = 0;

            if (!CanEvaluateRange(
                mode,
                minDistance,
                maxDistance))
            {
                return false;
            }

            bool found = false;

            // 一覧を生成せず、最良候補のみを保持する。
            foreach (Vector2Int position in
                distanceMap.GetPositionsWithinDistance(
                    maxDistance))
            {
                int distance =
                    distanceMap.GetDistance(position);

                if (distance < minDistance)
                {
                    continue;
                }

                if (!TryEvaluateInternal(
                    position,
                    distance,
                    mode,
                    out var candidate))
                {
                    continue;
                }

                lastCandidateCount++;

                if (!found ||
                    IsBetterCandidate(
                        candidate,
                        evaluation))
                {
                    evaluation = candidate;

                    found = true;
                }
            }

            return found;
        }

        /// <summary>
        /// 指定された距離範囲の評価結果を取得する。
        /// </summary>
        /// <param name="mode">空間評価方式</param>
        /// <param name="results">評価結果の格納先</param>
        /// <param name="minDistance">最小移動距離</param>
        /// <param name="maxDistance">最大移動距離</param>
        /// <returns>取得した評価結果の件数</returns>
        /// <remarks>
        /// 格納先の一覧は最初に初期化する。
        /// 評価結果はグリッドの列挙順で格納する。
        /// 評価値による並べ替えは行わない。
        /// </remarks>
        /// <exception cref="ArgumentNullException">
        /// 格納先が指定されていない場合。
        /// </exception>
        public int GetEvaluations(
            MazeEnemySpatialMode mode,
            List<MazeEnemySpatialEvaluation> results,
            int minDistance = 1,
            int maxDistance = int.MaxValue)
        {
            if (results == null)
            {
                throw new ArgumentNullException(
                    nameof(results));
            }

            results.Clear();

            lastCandidateCount = 0;

            if (!CanEvaluateRange(
                mode,
                minDistance,
                maxDistance))
            {
                return 0;
            }

            foreach (Vector2Int position in
                distanceMap.GetPositionsWithinDistance(
                    maxDistance))
            {
                int distance =
                    distanceMap.GetDistance(position);

                if (distance < minDistance)
                {
                    continue;
                }

                if (TryEvaluateInternal(
                    position,
                    distance,
                    mode,
                    out var evaluation))
                {
                    results.Add(evaluation);
                }
            }

            lastCandidateCount = results.Count;

            return results.Count;
        }

        /// <summary>
        /// 計算済みの距離を使用して空間評価を行う。
        /// </summary>
        /// <param name="position">評価対象の座標</param>
        /// <param name="distance">起点からの最短移動距離</param>
        /// <param name="mode">空間評価方式</param>
        /// <param name="evaluation">空間評価結果</param>
        /// <returns>評価に成功した場合はtrue</returns>
        private bool TryEvaluateInternal(
            Vector2Int position,
            int distance,
            MazeEnemySpatialMode mode,
            out MazeEnemySpatialEvaluation evaluation)
        {
            evaluation = default;

            // 到達不可能なセルと起点自身を除外する。
            if (distance <= 0)
            {
                return false;
            }

            // 自身の距離マップから到達可能性は確認済み。
            // 縄張り中心が無効な場合は縄張り評価を適用しない。
            bool hasTerritoryEvaluation =
                territory.TryEvaluate(
                    position,
                    out var territoryEvaluation);

            float territoryMultiplier =
                hasTerritoryEvaluation
                    ? territoryEvaluation.PreferenceMultiplier
                    : 1f;

            float unvisitedScore = Mathf.Clamp01(
                context.GetUnvisitedScore(position));

            float distanceScore =
                1f / (1f + distance / ReferenceDistance);

            float preference;
            float score;

            switch (mode)
            {
                case MazeEnemySpatialMode.Exploration:

                    preference = context.GetParameterValue(
                        MazeEnemyParameter.Exploration);

                    // 探索傾向に応じて未訪問度を重視する。
                    float explorationScore =
                        Mathf.Lerp(
                            1f,
                            unvisitedScore,
                            preference);

                    // 遠い地点への探索も許容する。
                    float explorationDistanceScore =
                        Mathf.Lerp(
                            0.5f,
                            1f,
                            distanceScore);

                    score =
                        explorationScore *
                        explorationDistanceScore *
                        territoryMultiplier;

                    break;

                case MazeEnemySpatialMode.Patrol:

                    preference = context.GetParameterValue(
                        MazeEnemyParameter.PatrolPreference);

                    // 訪問済みの地点にも一定の評価を残す。
                    float patrolMemoryScore =
                        Mathf.Lerp(
                            0.25f,
                            1f,
                            unvisitedScore);

                    // 巡回傾向に応じて近い地点を重視する。
                    float patrolDistanceScore =
                        Mathf.Lerp(
                            1f,
                            distanceScore,
                            preference);

                    score =
                        patrolMemoryScore *
                        patrolDistanceScore *
                        territoryMultiplier;

                    break;

                default:

                    return false;
            }

            evaluation = new MazeEnemySpatialEvaluation(
                position,
                cachedOrigin,
                mode,
                distance,
                distanceScore,
                unvisitedScore,
                preference,
                territoryEvaluation,
                territoryMultiplier,
                Mathf.Clamp01(score));

            return true;
        }

        /// <summary>
        /// 指定された評価方式と距離範囲が利用可能か確認する。
        /// </summary>
        /// <param name="mode">空間評価方式</param>
        /// <param name="minDistance">最小移動距離</param>
        /// <param name="maxDistance">最大移動距離</param>
        /// <returns>評価可能な場合はtrue</returns>
        private bool CanEvaluateRange(
            MazeEnemySpatialMode mode,
            int minDistance,
            int maxDistance)
        {
            if (!IsSupportedMode(mode) ||
                minDistance < 1 ||
                maxDistance < minDistance)
            {
                return false;
            }

            return Refresh();
        }

        /// <summary>
        /// 対応する空間評価方式であるか確認する。
        /// </summary>
        /// <param name="mode">空間評価方式</param>
        /// <returns>対応する評価方式の場合はtrue</returns>
        private static bool IsSupportedMode(
            MazeEnemySpatialMode mode)
        {
            return mode == MazeEnemySpatialMode.Exploration ||
                mode == MazeEnemySpatialMode.Patrol;
        }

        /// <summary>
        /// 候補が現在の最良候補より適切であるか確認する。
        /// </summary>
        /// <param name="candidate">比較対象の候補</param>
        /// <param name="currentBest">現在の最良候補</param>
        /// <returns>比較対象の方が適切な場合はtrue</returns>
        private static bool IsBetterCandidate(
            MazeEnemySpatialEvaluation candidate,
            MazeEnemySpatialEvaluation currentBest)
        {
            float difference =
                candidate.Score - currentBest.Score;

            if (difference > ScoreTolerance)
            {
                return true;
            }

            if (Mathf.Abs(difference) <= ScoreTolerance)
            {
                return candidate.Distance <
                    currentBest.Distance;
            }

            return false;
        }

        /// <summary>
        /// グリッドのセル変更を処理する。
        /// </summary>
        /// <param name="position">変更されたセル座標</param>
        /// <param name="previousCell">変更前のセル情報</param>
        /// <param name="newCell">変更後のセル情報</param>
        private void HandleCellChanged(
            Vector2Int position,
            MazeCell previousCell,
            MazeCell newCell)
        {
            if (isDisposed)
            {
                return;
            }

            // 通行可能性が変化した場合のみ無効化する。
            if (previousCell.IsWalkable !=
                newCell.IsWalkable)
            {
                isDirty = true;
            }
        }

        /// <summary>
        /// 空間評価システムを破棄する。
        /// </summary>
        /// <remarks>
        /// コンテキストや縄張り評価システムは破棄しない。
        /// 複数回呼び出しても安全に処理する。
        /// </remarks>
        public void Dispose()
        {
            if (isDisposed)
            {
                return;
            }

            isDisposed = true;

            map.CellChanged -= HandleCellChanged;

            distanceMap.Clear();

            isDirty = false;

            lastCandidateCount = 0;
        }
    }
}
